import { computed, defineComponent, h, nextTick, onBeforeUnmount, onMounted, ref, useId, watch, Teleport, type PropType } from 'vue';
import { comboboxStyleKeys, filterComboboxItems, getSelectState, moveComboboxIndex } from '../lib/core';
import type { ComboboxItem } from '../lib/core';
import { usePortalContainer, type PortalContainer } from '../portal';
import styles from './combobox.module.scss';

function comboboxCheckIcon() {
	return h(
		'svg',
		{
			xmlns: 'http://www.w3.org/2000/svg',
			width: '16',
			height: '16',
			viewBox: '0 0 24 24',
			fill: 'none',
			stroke: 'currentColor',
			'stroke-width': '2',
			'stroke-linecap': 'round',
			'stroke-linejoin': 'round',
			'aria-hidden': 'true',
		},
		[h('path', { d: 'M20 6 9 17l-5-5' })],
	);
}

function comboboxChevronIcon() {
	return h(
		'svg',
		{
			class: styles[comboboxStyleKeys.triggerIcon],
			xmlns: 'http://www.w3.org/2000/svg',
			width: '16',
			height: '16',
			viewBox: '0 0 24 24',
			fill: 'none',
			stroke: 'currentColor',
			'stroke-width': '2',
			'stroke-linecap': 'round',
			'stroke-linejoin': 'round',
			'aria-hidden': 'true',
		},
		[h('path', { d: 'm6 9 6 6 6-6' })],
	);
}

export const Combobox = defineComponent({
	name: 'Combobox',
	inheritAttrs: false,
	props: {
		items: { type: Array as PropType<ComboboxItem[]>, required: true },
		value: { type: String, default: undefined },
		defaultValue: { type: String, default: undefined },
		placeholder: { type: String, default: 'Select...' },
		searchPlaceholder: { type: String, default: 'Search...' },
		emptyText: { type: String, default: 'No items.' },
		notFoundText: { type: String, default: 'No results found.' },
		maxItems: { type: Number, default: undefined },
		disabled: { type: Boolean, default: false },
		filter: { type: Function as PropType<(item: ComboboxItem, query: string) => boolean>, default: undefined },
		container: { type: Object as PropType<PortalContainer>, default: null },
	},
	emits: ['update:value'],
	setup(props, { emit, attrs }) {
		const portalContainer = usePortalContainer(() => props.container);
		const open = ref(false);
		const query = ref('');
		const activeValue = ref<string | null>(null);
		const internalValue = ref(props.defaultValue);
		const triggerRef = ref<HTMLButtonElement | null>(null);
		const contentRef = ref<HTMLElement | null>(null);
		const contentId = `tile-combobox-${useId()}`;

		const currentValue = computed(() => (props.value !== undefined ? props.value : internalValue.value));
		const filteredItems = computed(() => filterComboboxItems(props.items, query.value, props.maxItems, props.filter));
		const selectedItem = computed(() => props.items.find((item) => item.value === currentValue.value));

		function setOpenState(next: boolean) {
			open.value = next;
			if (!next) {
				query.value = '';
				activeValue.value = null;
			}
		}

		function handleTriggerClick() {
			if (props.disabled) {
				return;
			}
			setOpenState(!open.value);
		}

		function handleSelect(item: ComboboxItem) {
			if (item.disabled) {
				return;
			}
			if (props.value === undefined) {
				internalValue.value = item.value;
			}
			emit('update:value', item.value);
			setOpenState(false);
		}

		function handleTriggerKeyDown(event: KeyboardEvent) {
			if (event.key === 'Enter' || event.key === ' ' || event.key === 'ArrowDown' || event.key === 'ArrowUp') {
				event.preventDefault();
				if (props.disabled) {
					return;
				}
				setOpenState(true);
			}
		}

		function handleContentKeyDown(event: KeyboardEvent) {
			const enabledItems = filteredItems.value.filter((item) => !item.disabled);
			if (enabledItems.length === 0) {
				if (event.key === 'Escape') {
					event.preventDefault();
					setOpenState(false);
				}
				return;
			}

			const currentIndex = enabledItems.findIndex((item) => item.value === activeValue.value);

			switch (event.key) {
				case 'ArrowDown':
					event.preventDefault();
					activeValue.value = enabledItems[moveComboboxIndex(currentIndex, 1, enabledItems.length)].value;
					break;
				case 'ArrowUp':
					event.preventDefault();
					activeValue.value = enabledItems[moveComboboxIndex(currentIndex, -1, enabledItems.length)].value;
					break;
				case 'Home':
					event.preventDefault();
					activeValue.value = enabledItems[0].value;
					break;
				case 'End':
					event.preventDefault();
					activeValue.value = enabledItems[enabledItems.length - 1].value;
					break;
				case 'Enter':
				case ' ':
					event.preventDefault();
					handleSelect(enabledItems[currentIndex >= 0 ? currentIndex : 0]);
					break;
				case 'Escape':
					event.preventDefault();
					setOpenState(false);
					triggerRef.value?.focus();
					break;
			}
		}

		let disposeDocListeners: (() => void) | null = null;

		function updatePosition() {
			const trigger = triggerRef.value;
			const content = contentRef.value;
			if (!trigger || !content) {
				return;
			}
			const triggerRect = trigger.getBoundingClientRect();
			const contentSize = { width: content.offsetWidth, height: content.offsetHeight };
			const viewport = { width: window.innerWidth, height: window.innerHeight };
			const margin = 8;
			const left = Math.min(Math.max(triggerRect.left, margin), Math.max(margin, viewport.width - contentSize.width - margin));
			const top = Math.min(Math.max(triggerRect.bottom + 4, margin), Math.max(margin, viewport.height - contentSize.height - margin));
			content.style.top = `${top}px`;
			content.style.left = `${left}px`;
		}

		function handleOpen() {
			// 内容通过 Teleport 条件渲染，需等组件挂载后再定位，否则 contentRef 为空、弹层停留在文档末尾。
			nextTick(() => updatePosition());
			window.addEventListener('resize', updatePosition);
			document.addEventListener('scroll', updatePosition, true);

			function handlePointerDown(event: PointerEvent) {
				const target = event.target as Node | null;
				const content = contentRef.value;
				const trigger = triggerRef.value;
				if (!target) {
					return;
				}
				if (content && content.contains(target)) {
					return;
				}
				if (trigger && trigger.contains(target)) {
					return;
				}
				setOpenState(false);
			}

			document.addEventListener('pointerdown', handlePointerDown);
			disposeDocListeners = () => document.removeEventListener('pointerdown', handlePointerDown);
		}

		function handleClose() {
			window.removeEventListener('resize', updatePosition);
			document.removeEventListener('scroll', updatePosition, true);
			disposeDocListeners?.();
			disposeDocListeners = null;
		}

		onMounted(() => {
			if (open.value) {
				handleOpen();
			}
		});

		watch(open, (next) => {
			if (next) {
				handleOpen();
			} else {
				handleClose();
			}
		});

		onBeforeUnmount(handleClose);

		return () => {
			const showEmpty = filteredItems.value.length === 0;
			const emptyMessage = query.value ? props.notFoundText : props.emptyText;
			const userClass = attrs.class;

			const content = h(
				'div',
				{
					ref: contentRef,
					id: contentId,
					role: 'listbox',
					tabindex: -1,
					'data-state': getSelectState(open.value),
					class: styles[comboboxStyleKeys.content],
					onKeydown: handleContentKeyDown,
				},
				[
					h('div', { class: styles[comboboxStyleKeys.search] }, [
						h('input', {
							role: 'combobox',
							'aria-expanded': open.value,
							'aria-controls': contentId,
							'aria-autocomplete': 'list',
							class: styles[comboboxStyleKeys.searchInput],
							value: query.value,
							placeholder: props.searchPlaceholder,
							onInput: (event: Event) => {
								query.value = (event.target as HTMLInputElement).value;
								activeValue.value = null;
							},
						}),
					]),
					h('div', { class: styles[comboboxStyleKeys.list] }, [
						showEmpty
							? h('div', { class: styles[comboboxStyleKeys.empty] }, [emptyMessage])
							: filteredItems.value.map((item) =>
									h(
										'div',
										{
											key: item.value,
											role: 'option',
											tabindex: -1,
											'aria-selected': item.value === currentValue.value,
											'data-highlighted': activeValue.value === item.value,
											'data-disabled': item.disabled,
											class: styles[comboboxStyleKeys.item],
											onMouseenter: () => {
												if (!item.disabled) {
													activeValue.value = item.value;
												}
											},
											onClick: () => handleSelect(item),
										},
										[
											h('span', { class: styles[comboboxStyleKeys.itemIndicator] }, [item.value === currentValue.value ? comboboxCheckIcon() : null]),
											item.label,
										],
									),
								),
					]),
				],
			);

			return h('div', { ...attrs, class: [styles[comboboxStyleKeys.root], userClass] }, [
				h(
					'button',
					{
						ref: triggerRef,
						type: 'button',
						'aria-haspopup': 'listbox',
						'aria-expanded': open.value,
						'aria-controls': contentId,
						'data-disabled': props.disabled,
						class: styles[comboboxStyleKeys.trigger],
						onClick: handleTriggerClick,
						onKeydown: handleTriggerKeyDown,
					},
					[
						h('span', { 'data-placeholder': !selectedItem.value, class: styles[comboboxStyleKeys.triggerValue] }, [selectedItem.value?.label ?? props.placeholder]),
						comboboxChevronIcon(),
					],
				),
				open.value ? h(Teleport, { to: portalContainer.value }, [content]) : null,
			]);
		};
	},
});

export default Combobox;

@use '../../../styles/variables/colors' as *;

// 根容器
.root {
	position: relative;
	display: inline-flex;
	width: 100%;
}

// 触发器按钮
.trigger {
	display: inline-flex;
	width: 100%;
	min-height: var(--tile-combobox-trigger-min-height, auto);
	align-items: center;
	justify-content: space-between;
	gap: $spacing-2;
	border-radius: var(--tile-select-trigger-radius, $radius);
	border: 1px solid var(--tile-select-trigger-border, $input);
	background-color: var(--tile-select-trigger-background, transparent);
	padding: var(--tile-select-trigger-padding, $spacing-2 $spacing-3);
	font-size: var(--tile-select-font-size, $text-sm);
	white-space: nowrap;
	color: var(--tile-select-foreground, $foreground);
	box-shadow: var(--tile-select-trigger-shadow, $shadow-sm);
	transition:
		color $transition-fast,
		box-shadow $transition-fast;
	outline: none;
	cursor: pointer;

	&:focus-visible {
		border-color: var(--tile-select-focus-border, $ring);
		box-shadow: var(--tile-select-focus-shadow, 0 0 0 3px color-mix(in srgb, $ring 50%, transparent));
	}

	&[data-disabled='true'] {
		cursor: not-allowed;
		opacity: 0.5;
	}
}

// 触发器展示文本
.triggerValue {
	display: flex;
	flex: 1;
	align-items: center;
	gap: $spacing-2;
	overflow: hidden;
	text-align: left;

	&[data-placeholder='true'] {
		color: var(--tile-select-placeholder, $muted-foreground);
	}
}

// 触发器箭头
.triggerIcon {
	pointer-events: none;
	flex-shrink: 0;
	width: 1rem;
	height: 1rem;
	color: var(--tile-select-subtle, $muted-foreground);
}

// 弹出内容面板
.content {
	position: fixed;
	z-index: $z-dropdown;
	width: max-content;
	min-width: 8rem;
	max-height: 24rem;
	overflow: hidden;
	border-radius: var(--tile-select-panel-radius, $radius);
	border: 1px solid var(--tile-select-panel-border, $border);
	background-color: var(--tile-select-panel-background, $popover);
	color: var(--tile-select-panel-foreground, $popover-foreground);
	box-shadow: var(--tile-select-panel-shadow, $shadow-md);
	outline: none;
	transition:
		opacity $transition-fast,
		visibility $transition-fast,
		transform $transition-fast;

	&[data-state='closed'] {
		opacity: 0;
		visibility: hidden;
		pointer-events: none;
		transform: translateY(-0.25rem) scale(0.95);
	}

	&[data-state='open'] {
		opacity: 1;
		visibility: visible;
		pointer-events: auto;
		transform: translate(0, 0) scale(1);
	}
}

// 搜索框容器
.search {
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-bottom: 1px solid var(--tile-select-separator, $border);
	padding: var(--tile-combobox-search-padding, $spacing-2);
}

// 搜索输入框
.searchInput {
	width: 100%;
	border: none;
	background: transparent;
	padding: 0;
	font-size: var(--tile-select-font-size, $text-sm);
	color: var(--tile-select-foreground, $foreground);
	outline: none;

	&::placeholder {
		color: var(--tile-select-placeholder, $muted-foreground);
	}
}

// 候选项列表
.list {
	max-height: 15rem;
	overflow-x: hidden;
	overflow-y: auto;
	padding: var(--tile-combobox-list-padding, $spacing-1);
}

// 候选项
.item {
	position: relative;
	display: flex;
	width: 100%;
	align-items: center;
	gap: $spacing-2;
	border-radius: var(--tile-select-item-radius, $radius-sm);
	padding: var(--tile-select-item-padding, $spacing-1_5 $spacing-2 $spacing-1_5 $spacing-8);
	font-size: var(--tile-select-font-size, $text-sm);
	line-height: $leading-normal;
	color: var(--tile-select-panel-foreground, $popover-foreground);
	outline: none;
	cursor: default;
	user-select: none;

	&[data-highlighted='true'] {
		background-color: var(--tile-select-highlight-background, $accent);
		color: var(--tile-select-highlight-foreground, $accent-foreground);
	}

	&[data-disabled='true'] {
		pointer-events: none;
		opacity: 0.5;
	}

	&:focus-visible {
		box-shadow: var(--tile-select-item-focus-shadow, none);
	}
}

// 选中指示器
.itemIndicator {
	position: absolute;
	left: var(--tile-select-indicator-left, $spacing-2);
	right: var(--tile-select-indicator-right, auto);
	display: inline-flex;
	width: 0.875rem;
	height: 0.875rem;
	align-items: center;
	justify-content: center;

	& > svg {
		width: 1rem;
		height: 1rem;
	}
}

// 空状态提示
.empty {
	display: flex;
	width: 100%;
	align-items: center;
	justify-content: center;
	padding: $spacing-6;
	text-align: center;
	font-size: var(--tile-select-font-size, $text-sm);
	color: var(--tile-select-subtle, $muted-foreground);
}

// 分组容器
.group {
	display: block;
}

// 分组标题
.label {
	padding: var(--tile-select-label-padding, $spacing-1_5 $spacing-2);
	font-size: var(--tile-select-label-font-size, $text-xs);
	font-weight: var(--tile-select-label-font-weight, $font-medium);
	color: var(--tile-select-subtle, $muted-foreground);
}

// 分隔线
.separator {
	margin: $spacing-1 (-$spacing-1);
	height: 1px;
	background-color: var(--tile-select-separator, $border);
}

@media (prefers-reduced-motion: reduce) {
	.content {
		transition: none;
	}
}
